//! The records Refine stores and exports. Every type here has a TypeScript twin in
//! `src/bindings/` (regenerated by `cargo test`), so the UI and the JSON export share one contract.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::settings::ProviderKind;
use crate::taxonomy::ErrorCategory;

/// Bump when a stored/exported record changes shape. Old rows are upgraded on read.
pub const SCHEMA_VERSION: u32 = 1;

/// CEFR level. Used to pitch explanations and suggestions just above where the learner is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum Cefr {
    A1,
    A2,
    B1,
    B2,
    C1,
    C2,
}

impl Cefr {
    pub const ALL: [Cefr; 6] = [Cefr::A1, Cefr::A2, Cefr::B1, Cefr::B2, Cefr::C1, Cefr::C2];

    pub fn as_str(self) -> &'static str {
        match self {
            Cefr::A1 => "A1",
            Cefr::A2 => "A2",
            Cefr::B1 => "B1",
            Cefr::B2 => "B2",
            Cefr::C1 => "C1",
            Cefr::C2 => "C2",
        }
    }

    pub fn parse(s: &str) -> Option<Cefr> {
        Cefr::ALL.into_iter().find(|c| c.as_str().eq_ignore_ascii_case(s.trim()))
    }

    /// One step up, capped at C2 ("i+1").
    pub fn next(self) -> Cefr {
        let i = Cefr::ALL.iter().position(|c| *c == self).unwrap_or(0);
        Cefr::ALL[(i + 1).min(Cefr::ALL.len() - 1)]
    }
}

/// What kind of improvement a suggestion offers (§3.6). Never counted as an error.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub enum SuggestionKind {
    /// Correct, but natives combine these words differently (a more common collocation).
    Collocation,
    /// Correct, but a native speaker would usually phrase it differently (idiom, construction).
    Phrase,
    /// Already good; a synonym or richer phrase to widen the learner's range.
    Synonym,
}

impl SuggestionKind {
    /// "More natural" (vs "more variety") in the UI.
    pub fn is_naturalness(self) -> bool {
        !matches!(self, SuggestionKind::Synonym)
    }
}

/// Where a phrase sits in a text, in UTF-16 code units (what JavaScript string indexes use).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct TextSpan {
    pub start: u32,
    pub end: u32,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub struct Mistake {
    /// Unique within its entry ("m1", "m2", ...).
    pub id: String,
    /// The exact wrong fragment from the input.
    pub original: String,
    pub correction: String,
    pub category: ErrorCategory,
    /// A reader could misunderstand or stumble (a "global" error, §3.2).
    pub impedes_meaning: bool,
    /// Plain-language explanation, a sentence or two.
    pub explanation: String,
    /// Short reusable name of the underlying rule or item ("dative after mit").
    pub pattern: String,
    /// `language:category:slug`; the same mistake in different texts shares it.
    pub pattern_key: String,
    /// Location of `original` in the input; `None` if it couldn't be located.
    pub span: Option<TextSpan>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub struct Suggestion {
    /// Unique within its entry ("s1", "s2", ...).
    pub id: String,
    pub kind: SuggestionKind,
    /// The fragment of the fixed text this is about.
    pub original: String,
    pub replacement: String,
    pub explanation: String,
    /// Rough CEFR level of the replacement.
    pub level: Cefr,
    /// Location of `original` in the fixed text.
    pub span: Option<TextSpan>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub enum DiffOp {
    Equal,
    Insert,
    Delete,
}

/// For a watched pattern: how often the text needed it, and how often it went wrong (§4.3).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub struct PatternCheck {
    pub key: String,
    pub label: String,
    pub correct: u32,
    pub errors: u32,
}

/// One run of the word diff between the input and the fixed text.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct DiffPart {
    pub op: DiffOp,
    pub text: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ToneRef {
    pub id: String,
    pub name: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub struct ModelRef {
    pub provider_id: String,
    pub provider_kind: ProviderKind,
    pub model: String,
}

/// One checked text: what the user wrote, what the model found, and when.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
#[serde(rename_all = "camelCase")]
pub struct Entry {
    pub schema_version: u32,
    /// UUID v7 (time-ordered).
    pub id: String,
    pub created_at: DateTime<Utc>,
    pub input: String,
    /// Language code of the text ("en", "de", ...).
    pub language: String,
    /// The learner's level in that language when the text was checked.
    pub level: Cefr,
    pub tone: ToneRef,
    pub model: ModelRef,
    pub fixed_text: String,
    pub mistakes: Vec<Mistake>,
    pub suggestions: Vec<Suggestion>,
    /// Opportunity counts for the patterns that were on the watch list at check time.
    #[serde(default)]
    pub watch: Vec<PatternCheck>,
    pub diff: Vec<DiffPart>,
    pub word_count: u32,
    #[ts(type = "number")]
    pub duration_ms: u64,
    /// Problems Refine noticed in the model's answer and worked around.
    pub warnings: Vec<String>,
}

/// `de:grammar.case:dative-after-mit`. Labels are lowercased and reduced to letters and digits,
/// so small wording differences ("Dative after 'mit'") still meet.
pub fn pattern_key(language: &str, category: ErrorCategory, label: &str) -> String {
    let slug: String = label
        .to_lowercase()
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    format!("{language}:{}:{slug}", category.id())
}
